insert into exercises (name, slug, description, instructions, main_muscle, secondary_muscles, equipment, difficulty, type, image_url, images, force, mechanic, common_mistakes, tips, recommended_sets, recommended_reps, recommended_rest_seconds, alternatives) values
('3/4 Sit-Up','3-4-sit-up','Ejercicio de tirón, compuesto.',ARRAY['Lie down on the floor and secure your feet. Your legs should be bent at the knees.','Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.','Flex your hips and spine to raise your torso toward your knees.','At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/3_4_Sit-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/3_4_Sit-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/3_4_Sit-Up/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Air Bike','air-bike','Ejercicio de tirón, compuesto.',ARRAY['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.','Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.','Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.','Go back to the initial position as you breathe in.','Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.','Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Air_Bike/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Air_Bike/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Air_Bike/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Ab Rollout','barbell-ab-rollout','Ejercicio de tirón, compuesto.',ARRAY['For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.','While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.','After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY['espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Rollout from Bench','barbell-rollout-from-bench','Ejercicio de tirón, compuesto.',ARRAY['Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position.','To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.','When the bar has been moved as far forward as possible, return to the starting position.']::text[],'abdomen',ARRAY['gluteos','piernas','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rollout_from_Bench/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rollout_from_Bench/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Rollout_from_Bench/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bent-Knee Hip Raise','bent-knee-hip-raise','Ejercicio de tirón, compuesto.',ARRAY['Lay flat on the floor with your arms next to your sides.','Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.','Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.','Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Knee_Hip_Raise/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Knee_Hip_Raise/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent-Knee_Hip_Raise/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bottoms Up','bottoms-up','Ejercicio de tirón, compuesto.',ARRAY['Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position.','To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor.','After a brief pause, return to the starting position.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms_Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms_Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms_Up/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Butt-Ups','butt-ups','Ejercicio de tirón, compuesto.',ARRAY['Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle.','Arch your back slightly out rather than keeping your back completely straight.','Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of the movement.','Lower back down slowly to your starting position as you breathe in. Tip: Don''t let your back sag downwards.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butt-Ups/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butt-Ups/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Butt-Ups/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Judo Flip','cable-judo-flip','Ejercicio de tirón, compuesto.',ARRAY['Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands.','Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip.','Shift your weight between your feet as you twist and crunch forward, pulling the cable downward.','Return to the starting position and repeat until failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Judo_Flip/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Judo_Flip/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Judo_Flip/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Russian Twists','cable-russian-twists','Ejercicio de tirón, compuesto.',ARRAY['Connect a standard handle attachment, and position the cable to a middle pulley position.','Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.','Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.','Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.','Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.','Repeat the same movement to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Russian_Twists/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Russian_Twists/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Russian_Twists/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cocoons','cocoons','Ejercicio de tirón, compuesto.',ARRAY['Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position.','To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion.','After a brief pause, return to the starting position.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cocoons/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cocoons/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cocoons/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cross-Body Crunch','cross-body-crunch','Ejercicio de tirón, compuesto.',ARRAY['Lie flat on your back and bend your knees about 60 degrees.','Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.','Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.','Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.','Continue alternating in this manner until all prescribed repetitions are done.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross-Body_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross-Body_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross-Body_Crunch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dead Bug','dead-bug','Ejercicio de tirón, compuesto.',ARRAY['Begin lying on your back with your hands extended above you toward the ceiling.','Bring your feet, knees, and hips up to 90 degrees.','Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.','Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.','Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.','Stay tight and return the working leg to the starting position.','Repeat on the opposite side, alternating until the set is complete.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dead_Bug/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dead_Bug/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dead_Bug/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Decline Oblique Crunch','decline-oblique-crunch','Ejercicio de tirón, compuesto.',ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.','Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.','Put one hand beside your head and the other on your thigh. This will be your starting position.','Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.','Lower your body back down slowly to the starting position as you inhale.','After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Oblique_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Oblique_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Oblique_Crunch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Decline Reverse Crunch','decline-reverse-crunch','Ejercicio de tirón, compuesto.',ARRAY['Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position.','Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.','While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.','Hold the contraction for a second and move your legs back to the starting position while inhaling.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Reverse_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Reverse_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Decline_Reverse_Crunch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Elbow to Knee','elbow-to-knee','Ejercicio de tirón, compuesto.',ARRAY['Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position.','Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee.','Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elbow_to_Knee/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elbow_to_Knee/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Elbow_to_Knee/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Flat Bench Leg Pull-In','flat-bench-leg-pull-in','Ejercicio de tirón, compuesto.',ARRAY['Lie on an exercise mat or a flat bench with your legs off the end.','Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.','Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second.','As you breathe in, slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flat_Bench_Leg_Pull-In/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flat_Bench_Leg_Pull-In/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flat_Bench_Leg_Pull-In/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Gorilla Chin/Crunch','gorilla-chin-crunch','Ejercicio de tirón, compuesto.',ARRAY['Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width.','Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.','As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this point you should also be finishing the crunch at the same time.','Slowly start to inhale as you return to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY['biceps','espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Gorilla_Chin_Crunch/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Gorilla_Chin_Crunch/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Gorilla_Chin_Crunch/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Jackknife Sit-Up','jackknife-sit-up','Ejercicio de tirón, compuesto.',ARRAY['Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position.','As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor.','While inhaling, lower your arms and legs back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Jackknife_Sit-Up/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Jackknife_Sit-Up/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Jackknife_Sit-Up/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Kettlebell Pass Between The Legs','kettlebell-pass-between-the-legs','Ejercicio de tirón, compuesto.',ARRAY['Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.','Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a "W". Go back and forth for several repetitions.']::text[],'abdomen',ARRAY['gluteos','piernas','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Pass_Between_The_Legs/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Pass_Between_The_Legs/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Pass_Between_The_Legs/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Kettlebell Windmill','kettlebell-windmill','Ejercicio de tirón, compuesto.',ARRAY['Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell. Bending at the hip to one side, sticking your butt out, slowly lean until you can touch the floor with your free hand. Keep your eyes on the kettlebell that you hold over your head at all times.','Pause for a second after reaching the ground and reverse the motion back to the starting position.']::text[],'abdomen',ARRAY['gluteos','piernas','hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Windmill/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Windmill/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Kettlebell_Windmill/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Landmine 180''s','landmine-180s','Ejercicio de tirón, compuesto.',ARRAY['Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight.','Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.','Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise.','Reverse the motion to swing the weight all the way to the opposite side.','Continue alternating the movement until the set is complete.']::text[],'abdomen',ARRAY['gluteos','espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Landmine_180s/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Landmine_180s/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Landmine_180s/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Leg Pull-In','leg-pull-in','Ejercicio de tirón, compuesto.',ARRAY['Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position.','Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should always remain parallel to the floor.','Return to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg_Pull-In/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg_Pull-In/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Leg_Pull-In/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Pallof Press With Rotation','pallof-press-with-rotation','Ejercicio de tirón, compuesto.',ARRAY['Connect a standard handle to a tower, and position the cable to shoulder height.','With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.','With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time.','Facing forward, press the cable away from your chest. You core should be tight and engaged.','Keeping your hips straight, twist your torso away from the pulley until you get a full quarter rotation.','Maintain your rigid stance and straight arms. Return to the neutral position in a slow and controlled manner. Your arms should be extended in front of you.','With the side tension still engaging your core, bring your hands to your chest and immediately press outward to a fully extended position. This constitutes one rep.','Repeat to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],'abdomen',ARRAY['pecho','hombros','triceps']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pallof_Press_With_Rotation/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pallof_Press_With_Rotation/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Pallof_Press_With_Rotation/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Russian Twist','russian-twist','Ejercicio de tirón, compuesto.',ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.','Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.','Twist your torso to the right side until your arms are parallel with the floor while breathing out.','Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY['espalda']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Russian_Twist/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Russian_Twist/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Russian_Twist/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Seated Flat Bench Leg Pull-In','seated-flat-bench-leg-pull-in','Ejercicio de tirón, compuesto.',ARRAY['Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.','Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.','After a second pause, go back to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Flat_Bench_Leg_Pull-In/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Flat_Bench_Leg_Pull-In/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Seated_Flat_Bench_Leg_Pull-In/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Side Jackknife','side-jackknife','Ejercicio de tirón, compuesto.',ARRAY[]::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Side_Jackknife/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Side_Jackknife/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Side_Jackknife/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Spell Caster','spell-caster','Ejercicio de tirón, compuesto.',ARRAY['Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position.','Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.','Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side.','Continue alternating, rotating from one side to the other until the set is complete.']::text[],'abdomen',ARRAY['gluteos','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spell_Caster/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spell_Caster/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spell_Caster/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Spider Crawl','spider-crawl','Ejercicio de tirón, compuesto.',ARRAY['Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position.','Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible.','Return this leg to the starting position and repeat on the opposite side.']::text[],'abdomen',ARRAY['pecho','hombros','triceps']::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spider_Crawl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spider_Crawl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Spider_Crawl/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Standing Cable Lift','standing-cable-lift','Ejercicio de tirón, compuesto.',ARRAY['Connect a standard handle on a tower, and move the cable to the lowest pulley position.','With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.','With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.','In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.','Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.','Retract your arms and then your body. Return to the neutral position in a slow and controlled manner.','Repeat to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],'abdomen',ARRAY['hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Lift/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Lift/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Lift/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Standing Cable Wood Chop','standing-cable-wood-chop','Ejercicio de tirón, compuesto.',ARRAY['Connect a standard handle to a tower, and move the cable to the highest pulley position.','With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.','With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.','In one motion, pull the handle down and across your body to your front knee while rotating your torso.','Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.','Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.','Repeat to failure.','Then, reposition and repeat the same series of movements on the opposite side.']::text[],'abdomen',ARRAY['hombros']::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Wood_Chop/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Wood_Chop/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Standing_Cable_Wood_Chop/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Wind Sprints','wind-sprints','Ejercicio de tirón, compuesto.',ARRAY['Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position.','Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3','Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible.','Continue alternating between legs until the set is complete.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Wind_Sprints/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Wind_Sprints/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Wind_Sprints/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Ab Crunch Machine','ab-crunch-machine','Ejercicio de tirón, aislamiento.',ARRAY['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.','At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.','After a second pause, slowly return to the starting position as you breathe in.','Repeat the movement for the prescribed amount of repetitions.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Crunch_Machine/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Crunch_Machine/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Ab_Crunch_Machine/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Advanced Kettlebell Windmill','advanced-kettlebell-windmill','Ejercicio de empuje, aislamiento.',ARRAY['Clean and press a kettlebell overhead with one arm.','Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell.','Lower yourself as far as possible.','Pause for a second and reverse the motion back to the starting position.']::text[],'abdomen',ARRAY['gluteos','piernas','hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Advanced_Kettlebell_Windmill/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Advanced_Kettlebell_Windmill/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Advanced_Kettlebell_Windmill/1.jpg']::text[],'Empuje','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Alternate Heel Touchers','alternate-heel-touchers','Ejercicio de tirón, aislamiento.',ARRAY['Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.','Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.','Now go back slowly to the starting position as you inhale.','Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.','Continue alternating sides in this manner until all prescribed repetitions are done.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['peso_corporal','casa']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Heel_Touchers/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Heel_Touchers/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Heel_Touchers/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Ab Rollout - On Knees','barbell-ab-rollout-on-knees','Ejercicio de tirón, compuesto.',ARRAY['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.','Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.','Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.','After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[],'abdomen',ARRAY['espalda','hombros']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Ab_Rollout_-_On_Knees/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Barbell Side Bend','barbell-side-bend','Ejercicio de tirón, aislamiento.',ARRAY['Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position.','While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.','Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'abdomen',ARRAY['espalda']::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Bend/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Bend/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Side_Bend/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bent Press','bent-press','Ejercicio de tirón, compuesto.',ARRAY['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position.','Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.','Return to an upright position, with the kettlebell above your head. Return the kettlebell to the shoulder and repeat for the desired number of repetitions.']::text[],'abdomen',ARRAY['gluteos','piernas','espalda','hombros','triceps']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'avanzado','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Press/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Press/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bent_Press/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Bosu Ball Cable Crunch With Side Bends','bosu-ball-cable-crunch-with-side-bends','Ejercicio de tirón, aislamiento.',ARRAY['Connect a standard handle to each arm of a cable machine, and position them in the most downward position.','Grab a Bosu Ball and position it in front and center of the cable machine.','Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it.','With both hands, reach back and grab the handle of each cable.','With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your knees. Your hands should be at knee level.','Keep your arms straight and in-line with the upward angle of the cable. Elevate your torso in a crunching motion without dropping or bending your arms.','Maintain the rigid position with your arms. Slowly descend back to the starting position with your back arched around the Bosu Ball and your abdominals elongated.','Repeat the same series of movements to failure.','Once you reach failure, keep your abs tight and raise your torso into plank position so your back is elevated off the Bosu Ball.','Lower your arms down to your side; keep them straight. Start doing alternating side bends; reach for your heels! This finishing movement will focus on your obliques.']::text[],'abdomen',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Bottoms-Up Clean From The Hang Position','bottoms-up-clean-from-the-hang-position','Ejercicio de tirón, compuesto.',ARRAY['Initiate the exercise by standing upright with a kettlebell in one hand.','Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.']::text[],'biceps',ARRAY['hombros']::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Bottoms-Up_Clean_From_The_Hang_Position/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Drag Curl','drag-curl','Ejercicio de tirón, compuesto.',ARRAY['Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position.','As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.','Slowly go back to the starting position as you keep the bar in contact with the torso at all times.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Drag_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Drag_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Drag_Curl/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('High Cable Curls','high-cable-curls','Ejercicio de tirón, compuesto.',ARRAY['Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position.','Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.','Slowly bring back the arms to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/High_Cable_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/High_Cable_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/High_Cable_Curls/1.jpg']::text[],'Tirón','Compuesto',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Alternate Hammer Curl','alternate-hammer-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. This will be your starting position.','While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbells back to starting position as your breathe in.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Hammer_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Hammer_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Hammer_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Alternate Incline Dumbbell Curl','alternate-incline-dumbbell-curl','Ejercicio de tirón, aislamiento.',ARRAY['Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.','While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbell back to starting position as your breathe in.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Incline_Dumbbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Incline_Dumbbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Alternate_Incline_Dumbbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Curl','barbell-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Barbell Curls Lying Against An Incline','barbell-curls-lying-against-an-incline','Ejercicio de tirón, aislamiento.',ARRAY['Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position.','While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms.','After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curls_Lying_Against_An_Incline/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curls_Lying_Against_An_Incline/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Barbell_Curls_Lying_Against_An_Incline/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Hammer Curls - Rope Attachment','cable-hammer-curls-rope-attachment','Ejercicio de tirón, aislamiento.',ARRAY['Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.','Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.','Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.','Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.','After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Hammer_Curls_-_Rope_Attachment/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Preacher Curl','cable-preacher-curl','Ejercicio de tirón, aislamiento.',ARRAY['Place a preacher bench about 2 feet in front of a pulley machine.','Attach a straight bar to the low pulley.','Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley.','Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position.','Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this motion. Also, hold for a second at the top.','Now slowly lower the weight to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Preacher_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Preacher_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Preacher_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cable Wrist Curl','cable-wrist-curl','Ejercicio de tirón, aislamiento.',ARRAY['Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment.','Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.','Start out by curling your wrist upwards and exhaling. Keep the contraction for a second.','Slowly lower your wrists back down to the starting position while inhaling.','Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Wrist_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Wrist_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cable_Wrist_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Close-Grip EZ-Bar Curl with Band','close-grip-ez-bar-curl-with-band','Ejercicio de tirón, aislamiento.',ARRAY['Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.','While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Close-Grip EZ Bar Curl','close-grip-ez-bar-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position.','While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.','Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.','Slowly begin to bring the bar back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ_Bar_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ_Bar_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_EZ_Bar_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Close-Grip Standing Barbell Curl','close-grip-standing-barbell-curl','Ejercicio de tirón, aislamiento.',ARRAY['Hold a barbell with both hands, palms up and a few inches apart.','Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement.','Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip: Avoid bending the back or using swinging motions as you lift the weight. Only the forearms should move.','Slowly go back down to the starting position as you inhale.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Standing_Barbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Standing_Barbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Close-Grip_Standing_Barbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Concentration Curls','concentration-curls','Ejercicio de tirón, aislamiento.',ARRAY['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.','Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.','While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.','Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.','Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Concentration_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Concentration_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Concentration_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Cross Body Hammer Curl','cross-body-hammer-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.','While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.','Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.','Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Body_Hammer_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Body_Hammer_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Cross_Body_Hammer_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Alternate Bicep Curl','dumbbell-alternate-bicep-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs.','While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.','Slowly begin to bring the dumbbell back to the starting position as your breathe in. Tip: Remember to twist the palms back to the starting position (facing your thighs) as you come down.','Repeat the movement with the left hand. This equals one repetition.','Continue alternating in this manner for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Alternate_Bicep_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Alternate_Bicep_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Alternate_Bicep_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Bicep Curl','dumbbell-bicep-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.','Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.','Then, inhale and slowly begin to lower the dumbbells back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bicep_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bicep_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Bicep_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Dumbbell Lying Pronation','dumbbell-lying-pronation','Ejercicio de tirón, aislamiento.',ARRAY['Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.','Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.','Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. This will be your starting position.','As you breathe out, externally rotate your forearm so that the dumbbell is lifted forward as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is parallel to the floor. At this point you will hold the contraction for a second.','As you breathe in, slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Pronation/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Pronation/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Pronation/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Lying Supination','dumbbell-lying-supination','Ejercicio de tirón, aislamiento.',ARRAY['Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it.','Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.','Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to the floor (aligned with your torso at all times). This will be your starting position.','As you breathe out, externally rotate your forearm so that the dumbbell is lifted up in a semicircle motion as you maintain the 90 degree angle bend between the upper arms and the forearm. You will continue this external rotation until the forearm is perpendicular to the floor and the torso pointing towards the ceiling. At this point you will hold the contraction for a second.','As you breathe in, slowly go back to the starting position.','Repeat for the recommended amount of repetitions and then switch to the other arm.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Supination/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Supination/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Lying_Supination/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('Dumbbell Prone Incline Curl','dumbbell-prone-incline-curl','Ejercicio de tirón, aislamiento.',ARRAY['Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way).','Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.','Now keep your elbows in by your side and face the palms forward. This will be your starting position.','Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as you perform this portion of the movement and ensure that only the forearms move. The upper arms should remain stationary at all times.','Lower the dumbbells until your arms are fully extended.','Repeat for the recommended amount of times.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Prone_Incline_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Prone_Incline_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Dumbbell_Prone_Incline_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[]),
('EZ-Bar Curl','ez-bar-curl','Ejercicio de tirón, aislamiento.',ARRAY['Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.','Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.','Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.','Then inhale and slowly lower the bar back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/EZ-Bar_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Finger Curls','finger-curls','Ejercicio de tirón, aislamiento.',ARRAY['Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width.','Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.','Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers.','Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['barras','gimnasio_completo']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Finger_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Finger_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Finger_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Flexor Incline Dumbbell Curls','flexor-incline-dumbbell-curls','Ejercicio de tirón, aislamiento.',ARRAY['Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them.','Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand.','Let your arms hang down on your sides, with the elbows in, and turn the palms of your hands forward with the thumbs pointing away from the body. Tip: You will keep this hand position throughout the movement as there should not be any twisting of the hands as they come up. This will be your starting position.','Curl up the two dumbbells at the same time until your biceps are fully contracted and exhale. Tip: Do not swing the arms or use momentum. Keep a controlled motion at all times. Hold the contracted position for a second at the top.','As you inhale, slowly go back to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flexor_Incline_Dumbbell_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flexor_Incline_Dumbbell_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Flexor_Incline_Dumbbell_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Hammer Curls','hammer-curls','Ejercicio de tirón, aislamiento.',ARRAY['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.','The palms of the hands should be facing your torso. This will be your starting position.','Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.','After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Hammer_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Dumbbell Curl','incline-dumbbell-curl','Ejercicio de tirón, aislamiento.',ARRAY['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.','While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.','Slowly begin to bring the dumbbells back to starting position as your breathe in.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Dumbbell_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Hammer Curls','incline-hammer-curls','Ejercicio de tirón, aislamiento.',ARRAY['Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.','Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.','Continue to the top of the movement and pause, then slowly return to the start position.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Hammer_Curls/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Hammer_Curls/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Hammer_Curls/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Incline Inner Biceps Curl','incline-inner-biceps-curl','Ejercicio, aislamiento.',ARRAY['Hold a dumbbell in each hand and lie back on an incline bench.','The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position.','Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose.','After a second contraction at the top of the movement, start to inhale and slowly lower the weights back to the starting position using the same path used to bring them up.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['mancuernas']::equipment_type[],'principiante','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Inner_Biceps_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Inner_Biceps_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Incline_Inner_Biceps_Curl/1.jpg']::text[],null,'Aislamiento',ARRAY[]::text[],ARRAY[]::text[],3,'10-12',75,ARRAY[]::text[]),
('Lying Cable Curl','lying-cable-curl','Ejercicio de tirón, aislamiento.',ARRAY['Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip.','Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.','With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position.','While keeping your upper arms stationary and the elbows close to your body, curl the bar up slowly toward your chest as you breathe out and you squeeze the biceps.','After a second squeeze at the top of the movement, slowly return to the starting position.','Repeat for the recommended amount of repetitions.']::text[],'biceps',ARRAY[]::muscle_group_type[],ARRAY['maquinas','gimnasio_completo']::equipment_type[],'intermedio','fuerza','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Cable_Curl/0.jpg',ARRAY['https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Cable_Curl/0.jpg','https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises/Lying_Cable_Curl/1.jpg']::text[],'Tirón','Aislamiento',ARRAY[]::text[],ARRAY[]::text[],4,'8-12',90,ARRAY[]::text[])
